/**
 * Derive a container application's state from its health instance counters.
 * Priority: failed -> starting/scheduling -> active -> ready.
 */
function deriveContainerState(app: DashApplication): ContainerState {
	const { failed, starting, scheduling, active } = app.health.instances;
	if (failed > 0) {
		return "degraded";
	}
	if (starting > 0 || scheduling > 0) {
		return "provisioning";
	}
	if (active > 0) {
		return "active";
	}
	return "ready";
}

function colorContainerState(state: ContainerState): string {
	switch (state) {
		case "active":
			return green(state);
		case "degraded":
			return red(state);
		default:
			return state;
	}
}

